<script lang="ts">
 import {onMount} from 'svelte';import {Save,ChartNoAxesCombined,BookOpen,Pin,PinOff,Settings2,Wallet,ReceiptText,TriangleAlert,CalendarDays,ArrowUp,ArrowDown} from '@lucide/svelte';import {translator} from './i18n';
 export let language:'ru'|'ro';export let databaseId:string;export let period:string;export let charges:string;export let paid:string;export let balance:string;export let attention:number;export let onopen:(id:string)=>void;
 let pinned:string[]=[],configure=false,loadedId='';$:t=translator(language);
 const widgets=[{id:'balance',ru:'Остаток к оплате',ro:'Sold de achitat',icon:Wallet,action:'reports'},{id:'charges',ru:'Начисления',ro:'Calcule',icon:ReceiptText,action:'receipts'},{id:'paid',ru:'Поступило оплат',ro:'Plăți încasate',icon:Wallet,action:'payment-report'},{id:'attention',ru:'Требует внимания',ro:'Necesită atenție',icon:TriangleAlert,action:'readings'},{id:'period',ru:'Расчётный период',ro:'Perioada de calcul',icon:CalendarDays,action:'period'}];
 function read(){try{const saved=JSON.parse(localStorage.getItem('openhau-widgets-'+databaseId)||'[]');pinned=Array.isArray(saved)?saved.filter(id=>widgets.some(w=>w.id===id)):[];}catch{pinned=[];}loadedId=databaseId;}
 onMount(read);$:if(loadedId&&loadedId!==databaseId)read();
 function store(){localStorage.setItem('openhau-widgets-'+databaseId,JSON.stringify(pinned));}
 function toggle(id:string){pinned=pinned.includes(id)?pinned.filter(x=>x!==id):[...pinned,id];store();}
 function move(index:number,delta:number){const j=index+delta;if(j<0||j>=pinned.length)return;const copy=[...pinned];[copy[index],copy[j]]=[copy[j],copy[index]];pinned=copy;store();}
</script>
<aside class="desktop-widgets" aria-label={t('Рабочий стол','Spațiu de lucru')}>
 <button class="desktop-shortcut" onclick={()=>onopen('file:save')}><Save size={30}/><span>{t('Сохранить','Salvează')}</span></button><button class="desktop-shortcut" onclick={()=>onopen('overview')}><ChartNoAxesCombined size={32}/><span>{t('Обзор','Prezentare')}</span></button><button class="desktop-shortcut" onclick={()=>onopen('manual')}><BookOpen size={29}/><span>{t('Документация','Documentație')}</span></button>
 </aside><div class="widget-bottom"><button class="widget-configure" aria-expanded={configure} onclick={()=>configure=!configure}><Settings2 size={16}/>{t('Виджеты','Widgeturi')}</button>
 {#if configure}<section class="widget-options">{#each widgets as widget}<label class="check-row"><input type="checkbox" checked={pinned.includes(widget.id)} onchange={()=>toggle(widget.id)}/>{widget[language]}</label>{/each}</section>{/if}
 {#each pinned as id,index}{@const widget=widgets.find(w=>w.id===id)!}<section class="desktop-widget"><header><widget.icon size={17}/><span>{widget[language]}</span><button aria-label={t('Открепить виджет','Elimină widgetul')} title={t('Открепить','Elimină')} onclick={()=>toggle(id)}><PinOff size={14}/></button></header><button class="widget-value" onclick={()=>onopen(widget.action)}>{id==='balance'?balance:id==='charges'?charges:id==='paid'?paid:id==='attention'?attention:period}{#if ['balance','charges','paid'].includes(id)}<small>MDL</small>{/if}</button>{#if configure}<footer><button aria-label={t('Переместить выше','Mută mai sus')} onclick={()=>move(index,-1)} disabled={index===0}><ArrowUp size={14}/></button><button aria-label={t('Переместить ниже','Mută mai jos')} onclick={()=>move(index,1)} disabled={index===pinned.length-1}><ArrowDown size={14}/></button></footer>{/if}</section>{/each}
</div>
<style>.desktop-widgets{position:absolute;right:12px;top:16px;width:220px;max-height:calc(100% - 28px);overflow:auto;z-index:0;display:flex;flex-direction:column;align-items:stretch;gap:12px}.desktop-shortcut{align-self:flex-end;width:130px;display:flex;flex-direction:column;align-items:center;gap:9px;padding:10px;background:transparent;color:var(--text);border:0;font-size:12px}.desktop-shortcut :global(svg){color:var(--accent)}.widget-bottom{position:absolute;right:12px;bottom:12px;width:220px;display:flex;align-items:center;flex-direction:column;z-index:1;max-height:65%;overflow:auto}.widget-configure{align-self:flex-end;width:130px;justify-content:center;display:flex;gap:7px;align-items:center;background:transparent;border:0;color:var(--muted);padding:8px}.widget-options,.desktop-widget{padding:12px;background:color-mix(in srgb,var(--surface) 82%,transparent);backdrop-filter:blur(18px);border:1px solid var(--border)}.widget-options{display:grid;gap:10px}.desktop-widget header{display:flex;gap:7px;align-items:center;font-size:12px}.desktop-widget header span{flex:1}.desktop-widget header>button,.desktop-widget footer>button{background:transparent;border:0;color:var(--muted);padding:4px}.widget-value{display:flex;align-items:baseline;gap:6px;font-size:23px;font-weight:600;background:transparent;color:var(--text);border:0;padding:16px 0 4px;max-width:100%;overflow-wrap:anywhere}.widget-value small{font-size:11px;font-weight:400;color:var(--muted)}footer{display:flex;justify-content:flex-end}</style>
